-- Sabit şık düzeltmesi: "Hiçbiri"/"Hepsine" şıklı iki soru artık karıştırılmıyor;
-- açıklamalar doğru şıkkı harfle değil metniyle anıyor (şıklar ekranda karışık).
-- Yalnızca bu beş soruyu günceller; yönetimden düzenlenmiş ya da kapatılmış sorulara dokunmaz.

UPDATE questions SET payload = v.payload, explanation = v.explanation
  FROM (SELECT column7 AS payload, column9 AS explanation FROM (VALUES ('u3-k05', 'u3', 3, 'mcq', 'original', 'Hangisi iş fikrinin finansal olarak değerlendirilmesi ile ilgili söylenemez?', '{"choices":["Gelir gider tablosu geleceğe dair varsayımlardan oluşur","Başabaş noktası gelirlerin giderlere eşit olması için gereken noktayı ifade eder","Yatırım geri dönüş süreci, ilk yatırım tutarının ne zaman yatırılacağını ifade eder","İlk yatırım tutarına aynı zamanda başlangıç sermayesi adı verilir.","Yatırım geri dönüş süresi, elde edilen net kârın ilk yatırım tutarını ne zaman karşılayacağını ifade eder"]}', '{"index":3}', 'Kitabın cevap anahtarına göre söylenemeyecek ifade: "**İlk yatırım tutarına aynı zamanda başlangıç sermayesi adı verilir**". Gelir gider tablosu varsayımlara dayanır, başabaş noktası gelirin gideri karşıladığı noktadır, geri dönüş süresi net kârın ilk yatırımı ne zaman karşılayacağını gösterir.', 3, 'Kitap, 3. ünite, soru 5', 1))) AS v
  WHERE questions.id = 'u3-k05' AND questions.updated_at IS NULL;
UPDATE questions SET payload = v.payload, explanation = v.explanation
  FROM (SELECT column7 AS payload, column9 AS explanation FROM (VALUES ('u5-k04', 'u5', 5, 'mcq', 'original', 'Endüstri analizinde hangisi beş önemli analiz unsurundan biri değildir?', '{"choices":["Çalışanlar","Rakipler","Tedarikçiler","Müşteriler","Dağıtım kanalı elemanları"]}', '{"index":0}', 'Kitabın cevap anahtarına göre doğru cevap **çalışanlar**dır. Endüstri analizi firmanın dışındaki aktörlere (müşteriler, rakipler, tedarikçiler, kanal üyeleri, ikame ve yeni girenler) bakar; çalışanlar firmanın içindedir.', 1, 'Kitap, 5. ünite, soru 4', 1))) AS v
  WHERE questions.id = 'u5-k04' AND questions.updated_at IS NULL;
UPDATE questions SET payload = v.payload, explanation = v.explanation
  FROM (SELECT column7 AS payload, column9 AS explanation FROM (VALUES ('u6-k06', 'u6', 6, 'mcq', 'original', 'Tüzel kişilik hangi anda kazanılır?', '{"choices":["Şirket sözleşmesi imzalandığında","Sözleşmedeki imzaların noterde tasdik edildiği anda","Ticaret Müdürülüğüne tescil edildiği anda","Türkiye Ticaret Sicili Gazetesinde ilan edildiği anda","Hiçbiri"],"sabit":true}', '{"index":2}', 'Kitap açıkça belirtir: **tescil ile tüzel kişilik kazanılır**.', 1, 'Kitap, 6. ünite, soru 6', 1))) AS v
  WHERE questions.id = 'u6-k06' AND questions.updated_at IS NULL;
UPDATE questions SET payload = v.payload, explanation = v.explanation
  FROM (SELECT column7 AS payload, column9 AS explanation FROM (VALUES ('u6-k07', 'u6', 6, 'mcq', 'original', 'Limited şirkette yönetim ve temsil yetkisi kime aittir?', '{"choices":["Müdüre","Muhasebeciye","Avukata","Ortaklara","Hepsine"],"sabit":true}', '{"index":0}', 'Limited şirkette yönetim ve temsil, şirket sözleşmesiyle **müdür** sıfatı taşıyan kişilere verilir.', 1, 'Kitap, 6. ünite, soru 7 · Çıkmış soru 19', 1))) AS v
  WHERE questions.id = 'u6-k07' AND questions.updated_at IS NULL;
UPDATE questions SET payload = v.payload, explanation = v.explanation
  FROM (SELECT column7 AS payload, column9 AS explanation FROM (VALUES ('u6-k08', 'u6', 6, 'mcq', 'original', 'Sermayenin taahhüt edilmesinden aşağıdakilerden hangisi anlaşılmaz?', '{"choices":["Taahütle sorumluluk sona erer","sorumluluk miktarı taahhüt edilen miktarkadardır","taahhüt edilenin ödenmemesi çıkma nedeni olabilir","sermayenin tamamının taahhüt edilmesi gerekir","maddi varlıklarla taahhüt yerine getirilebilir"]}', '{"index":3}', 'Kitabın cevap anahtarına göre taahhütten anlaşılmayan: "**sermayenin tamamının taahhüt edilmesi gerekir**". Asgari sermaye öngörülen hallerde taahhüdün ¼''ü peşin, kalanı üç yıl içinde ödenir.', 3, 'Kitap, 6. ünite, soru 8', 1))) AS v
  WHERE questions.id = 'u6-k08' AND questions.updated_at IS NULL;
